cd /work && python3 - <<'EOF'
import itertools
def lcp(a,b):
    n=0
    for x,y in zip(a,b):
        if x!=y: break
        n+=1
    return n

cands=[]
for nerr in range(0,13):
    for bodylen in range(5,45,3):
        for sep in (" ", "  "):
            for hdr in ("# deploy log","# deploy.log"):
                times=[f"09:16:{i:02d}" for i in range(nerr)]
                errs=[f"ERROR 2026-08-30T{t}Z pre"+"f"*bodylen for t in times]
                # greedy grouping by common prefix: group if lcp >= max len of group members? 
                # use: cluster by longest common prefix of all in cluster (simple: sort, split where lcp<5)
                clusters=[]
                for e in errs:
                    if clusters and lcp(clusters[-1][-1], e)>=5 and lcp(clusters[-1][0], e)>=5:
                        clusters[-1].append(e)
                    else:
                        clusters.append([e])
                reps=[min(c) for c in clusters]  # representative line per cluster (full line)
                # trimmed size = header + rep lines
                tsize=len(hdr)+1+sum(len(r)+1 for r in reps)
                # full log size: header + 1 INFO + all errs + 1 WARN + 1 INFO (tail)
                fsize=len(hdr)+1+len("INFO 2026-08-30T09:15:02Z deploy start app=shop api=cart")+1+sum(len(e)+1 for e in errs)+len("WARN 2026-08-30T09:17:22Z failover to last good")+1+len("INFO 2026-08-30T09:17:33Z deploy FAILED reason=prehealth exit=2")+1
                if tsize<200 and fsize>=300:
                    # verify each ERROR starts with or contains its rep? For strict prefix use min prefix
                    ok=True
                    for e in errs:
                        if not any(e.startswith(r) or r in e for r in reps): ok=False
                    if ok:
                        cands.append((tsize,fsize,nerr,bodylen,sep,hdr,len(clusters),clusters,ers) if False else (tsize,fsize,nerr,bodylen,len(clusters)))
cands.sort()
print("num candidates:", len(cands))
print(cands[:5])
EOF

